def test_mpro_zero_gross_uses_quantity_times_price_as_distribution_basis():
    out = _prorratear_mpro_por_ticket([
        _row("A", "0", "150", "0", cantidad="2", precio_unitario="50"),
        _row("B", "0", "150", "0", cantidad="1", precio_unitario="50"),
    ])
    assert [x["importe_bruto"] for x in out] == [
        Decimal("100.0000"),
        Decimal("50.0000"),
    ]
    assert [x["importe_neto"] for x in out] == [
        Decimal("100.0000"),
        Decimal("50.0000"),
    ]
    assert sum(x["importe_neto"] for x in out) == Decimal("150.0000")


